func (e *executableSchema) Exec(ctx context.Context) graphql.ResponseHandler {
	opCtx := graphql.GetOperationContext(ctx)
	ec := newExecutionContext(opCtx, e, make(chan graphql.DeferredResult))
	inputUnmarshalers := func() *graphql.InputUnmarshalerIndex {
		return graphql.NewInputUnmarshalerIndex(
			graphql.NewInputUnmarshaler("ActorFilter", ec.unmarshalInputActorFilter),
			graphql.NewInputUnmarshaler("ActorOrderByInput", ec.unmarshalInputActorOrderByInput),
			graphql.NewInputUnmarshaler("AdditionalPhoneInput", ec.unmarshalInputAdditionalPhoneInput),
			graphql.NewInputUnmarshaler("DashboardCreateInput", ec.unmarshalInputDashboardCreateInput),
			graphql.NewInputUnmarshaler("DashboardFilterInput", ec.unmarshalInputDashboardFilterInput),
			graphql.NewInputUnmarshaler("DashboardGroupByInput", ec.unmarshalInputDashboardGroupByInput),
			graphql.NewInputUnmarshaler("DashboardOrderByInput", ec.unmarshalInputDashboardOrderByInput),
			graphql.NewInputUnmarshaler("DashboardOrderByWithGroupByInput", ec.unmarshalInputDashboardOrderByWithGroupByInput),
			graphql.NewInputUnmarshaler("DashboardUpdateInput", ec.unmarshalInputDashboardUpdateInput),
			graphql.NewInputUnmarshaler("DateTimeFilter", ec.unmarshalInputDateTimeFilter),
			graphql.NewInputUnmarshaler("EmailsCreateInput", ec.unmarshalInputEmailsCreateInput),
			graphql.NewInputUnmarshaler("EmailsFilter", ec.unmarshalInputEmailsFilter),
			graphql.NewInputUnmarshaler("EmailsOrderByInput", ec.unmarshalInputEmailsOrderByInput),
			graphql.NewInputUnmarshaler("FloatFilter", ec.unmarshalInputFloatFilter),
			graphql.NewInputUnmarshaler("FullNameCreateInput", ec.unmarshalInputFullNameCreateInput),
			graphql.NewInputUnmarshaler("FullNameFilter", ec.unmarshalInputFullNameFilter),
			graphql.NewInputUnmarshaler("FullNameGroupByInput", ec.unmarshalInputFullNameGroupByInput),
			graphql.NewInputUnmarshaler("FullNameOrderByInput", ec.unmarshalInputFullNameOrderByInput),
			graphql.NewInputUnmarshaler("LinkMetadataInput", ec.unmarshalInputLinkMetadataInput),
			graphql.NewInputUnmarshaler("LinksCreateInput", ec.unmarshalInputLinksCreateInput),
			graphql.NewInputUnmarshaler("LinksFilter", ec.unmarshalInputLinksFilter),
			graphql.NewInputUnmarshaler("LinksOrderByInput", ec.unmarshalInputLinksOrderByInput),
			graphql.NewInputUnmarshaler("PersonCreateInput", ec.unmarshalInputPersonCreateInput),
			graphql.NewInputUnmarshaler("PersonFilterInput", ec.unmarshalInputPersonFilterInput),
			graphql.NewInputUnmarshaler("PersonGroupByInput", ec.unmarshalInputPersonGroupByInput),
			graphql.NewInputUnmarshaler("PersonOrderByInput", ec.unmarshalInputPersonOrderByInput),
			graphql.NewInputUnmarshaler("PersonOrderByWithGroupByInput", ec.unmarshalInputPersonOrderByWithGroupByInput),
			graphql.NewInputUnmarshaler("PersonUpdateInput", ec.unmarshalInputPersonUpdateInput),
			graphql.NewInputUnmarshaler("PhonesCreateInput", ec.unmarshalInputPhonesCreateInput),
			graphql.NewInputUnmarshaler("PhonesFilter", ec.unmarshalInputPhonesFilter),
			graphql.NewInputUnmarshaler("PhonesOrderByInput", ec.unmarshalInputPhonesOrderByInput),
			graphql.NewInputUnmarshaler("RawJSONFilter", ec.unmarshalInputRawJSONFilter),
			graphql.NewInputUnmarshaler("StringFilter", ec.unmarshalInputStringFilter),
			graphql.NewInputUnmarshaler("UUIDFilter", ec.unmarshalInputUUIDFilter),
			graphql.NewInputUnmarshaler("WorkspaceMemberCreateInput", ec.unmarshalInputWorkspaceMemberCreateInput),
			graphql.NewInputUnmarshaler("WorkspaceMemberDateFormatEnumFilter", ec.unmarshalInputWorkspaceMemberDateFormatEnumFilter),
			graphql.NewInputUnmarshaler("WorkspaceMemberFilterInput", ec.unmarshalInputWorkspaceMemberFilterInput),
			graphql.NewInputUnmarshaler("WorkspaceMemberGroupByInput", ec.unmarshalInputWorkspaceMemberGroupByInput),
			graphql.NewInputUnmarshaler("WorkspaceMemberNumberFormatEnumFilter", ec.unmarshalInputWorkspaceMemberNumberFormatEnumFilter),
			graphql.NewInputUnmarshaler("WorkspaceMemberOrderByInput", ec.unmarshalInputWorkspaceMemberOrderByInput),
			graphql.NewInputUnmarshaler("WorkspaceMemberOrderByWithGroupByInput", ec.unmarshalInputWorkspaceMemberOrderByWithGroupByInput),
			graphql.NewInputUnmarshaler("WorkspaceMemberTimeFormatEnumFilter", ec.unmarshalInputWorkspaceMemberTimeFormatEnumFilter),
			graphql.NewInputUnmarshaler("WorkspaceMemberUpdateInput", ec.unmarshalInputWorkspaceMemberUpdateInput),
		)
	}
	first := true

	switch opCtx.Operation.Operation {
	case ast.Query:
		return func(ctx context.Context) *graphql.Response {
			var response graphql.Response
			var data graphql.Marshaler
			if first {
				first = false
				ctx = graphql.WithLazyInputUnmarshalerIndex(ctx, inputUnmarshalers)
				data = ec._Query(ctx, opCtx.Operation.SelectionSet)
			} else {
				if atomic.LoadInt32(&ec.PendingDeferred) > 0 {
					result := <-ec.DeferredResults
					atomic.AddInt32(&ec.PendingDeferred, -1)
					data = result.Result
					response.Path = result.Path
					response.Label = result.Label
					response.Errors = result.Errors
				} else {
					return nil
				}
			}
			var buf bytes.Buffer
			data.MarshalGQL(&buf)
			response.Data = buf.Bytes()
			if atomic.LoadInt32(&ec.Deferred) > 0 {
				hasNext := atomic.LoadInt32(&ec.PendingDeferred) > 0
				response.HasNext = &hasNext
			}

			return &response
		}
	case ast.Mutation:
		return func(ctx context.Context) *graphql.Response {
			if !first {
				return nil
			}
			first = false
			ctx = graphql.WithLazyInputUnmarshalerIndex(ctx, inputUnmarshalers)
			data := ec._Mutation(ctx, opCtx.Operation.SelectionSet)
			var buf bytes.Buffer
			data.MarshalGQL(&buf)

			return &graphql.Response{
				Data: buf.Bytes(),
			}
		}

	default:
		return graphql.OneShot(graphql.ErrorResponse(ctx, "unsupported GraphQL operation"))
	}
}

type executionContext struct {
	*graphql.ExecutionContextState[ResolverRoot, DirectiveRoot, ComplexityRoot]
}

func newExecutionContext(
	opCtx *graphql.OperationContext,
	execSchema *executableSchema,
	deferredResults chan graphql.DeferredResult,
) *executionContext {
	return &executionContext{
		ExecutionContextState: graphql.NewExecutionContextState[ResolverRoot, DirectiveRoot, ComplexityRoot](
			opCtx,
			(*graphql.ExecutableSchemaState[ResolverRoot, DirectiveRoot, ComplexityRoot])(execSchema),
			parsedSchema,
			deferredResults,
		),
	}
}

